let data = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => { data += chunk; });
process.stdin.on('end', () => {
    const tokens = data.trim().split(/\s+/).map(Number);
    const n = tokens[0];
    const grid = [];
    let idx = 1;
    for (let i = 0; i < n; i++) {
        grid.push(tokens.slice(idx, idx + n));
        idx += n;
    }

    // Localiza a posição do número ilegível (marcado com 0)
    let r = -1, c = -1;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 0) {
                r = i;
                c = j;
            }
        }
    }

    // A constante mágica é a soma de qualquer linha completa (sem o 0)
    let S = 0;
    for (let i = 0; i < n; i++) {
        if (i !== r) {
            S = grid[i].reduce((a, b) => a + b, 0);
            break;
        }
    }

    // O valor faltante completa a linha do 0 até a constante mágica
    const rowSum = grid[r].reduce((a, b) => a + b, 0);
    const value = S - rowSum;

    console.log(value);
    console.log(r + 1);
    console.log(c + 1);
});
